package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.util.*;
import org.apache.commons.codec.digest.DigestUtils;
/** Reviewed, recoverable terminal metadata; no message bodies or re-delivery. */
final class DeliveryArchive {
 private DeliveryArchive() {}
 static Map<String,Object> policy(Store.Db db)throws Exception{return db.one("SELECT revision,days FROM os_retention_policy WHERE singleton=1");}
 static Map<String,Object> page(Store.Db db)throws Exception{Service.requireAccountAdministrator(db,db.viewerId);return map("policy",policy(db),"holds",db.all("SELECT job_id,reason FROM os_retention_hold ORDER BY job_id"),"batches",db.all("SELECT batch_id,state,created,item_count FROM os_delivery_archive ORDER BY created DESC,batch_id"),"review",null,"receipt",null);}
 static String proof(Store.Db db,Object value)throws Exception{return DigestUtils.sha256Hex("delivery-archive-v1:"+JSON.writeValueAsString(map("actor",db.viewerId,"authority",db.one("SELECT auth_revision FROM os_user WHERE user_id=?",db.viewerId),"value",value)));}
 static List<Map<String,Object>> rows(Store.Db db,long cutoff)throws Exception{return db.all("SELECT "+Outbox.PUBLIC_COLUMNS+",reference_id FROM os_outbox WHERE "+DeliveryRetention.ELIGIBLE+" ORDER BY expires_at,job_id LIMIT 100",cutoff);}
 static List<Map<String,Object>> visible(List<Map<String,Object>> rows){var result=new ArrayList<Map<String,Object>>();for(var row:rows){var copy=new LinkedHashMap<>(row);copy.remove("reference_id");result.add(copy);}return result;}
 static Map<String,Object> receipt(Store.Db db,String key)throws Exception{var row=db.one("SELECT batch_id,state,created,item_count,detail FROM os_delivery_archive WHERE batch_id=?",key);if(row==null)throw new Failure(404,"Archive batch not found");return row;}
 static List<Map<String,Object>> contents(Store store,Map<String,Object> batch)throws Exception{var content=Outbox.decrypt(store.secret+":delivery-archive-v1",batch.get("envelope").toString());if(!batch.get("batch_id").equals(content.get("batch_id")))throw new Failure(409,"Archive envelope binding mismatch");return objects(content.get("rows"));}
 static void restorable(Store.Db db,List<Map<String,Object>> rows)throws Exception{for(var row:rows)if(db.count("SELECT COUNT(*) FROM os_outbox WHERE job_id=? OR (kind=? AND reference_id=?)",row.get("job_id"),row.get("kind"),row.get("reference_id"))!=0)throw new Failure(409,"Current delivery metadata conflicts with this archive; resolve the conflict first");}
 static Map<String,Object> command(Store store,Store.Db db,Object input,long now)throws Exception{
  Service.requireAccountAdministrator(db,db.viewerId);var body=object(input);String op=WorkJobs.text(body.get("operation"),20);require(Set.of("policy","hold","release","review","archive","review_restore","restore").contains(op),"Choose a supported retention operation");var current=policy(db);
  if(Set.of("policy","hold","release").contains(op)){
   Set<String> fields=op.equals("policy")?Set.of("operation","revision","days"):op.equals("hold")?Set.of("operation","revision","job_id","reason"):Set.of("operation","revision","job_id");require(body.keySet().equals(fields),"Provide exact policy or hold fields");if(!current.get("revision").toString().equals(Objects.toString(body.get("revision"),"")))throw new Failure(409,"Retention policy changed; reload before editing");
   if(op.equals("policy")){String days=Objects.toString(body.get("days"),"");require(days.matches("[1-9][0-9]{1,3}"),"Use integer retention days");int n=Integer.parseInt(days);require(n>=30 && n<=3650,"Choose 30–3650 days");db.update("UPDATE os_retention_policy SET days=? WHERE singleton=1",n);}
   else{String job=WorkJobs.text(body.get("job_id"),32);require(job.matches("[0-9a-f]{32}"),"Use an exact delivery job ID");if(op.equals("hold")){require(db.count("SELECT COUNT(*) FROM os_outbox WHERE job_id=?",job)==1,"Choose existing delivery metadata");String reason=WorkJobs.text(body.get("reason"),500);require(db.count("SELECT COUNT(*) FROM os_retention_hold")<1000,"Retention hold capacity reached");db.update("INSERT INTO os_retention_hold(job_id,reason) VALUES(?,?) ON CONFLICT(job_id) DO UPDATE SET reason=excluded.reason",job,reason);}else if(db.update("DELETE FROM os_retention_hold WHERE job_id=?",job)==0)throw new Failure(404,"Retention hold not found");}
   db.update("UPDATE os_retention_policy SET revision=revision+1 WHERE singleton=1");SecurityEvents.record(db,db.viewerId,db.viewerId,"delivery.retention_changed",map("operation",op,"revision",((Number)current.get("revision")).longValue()+1));return map("review",null,"receipt",null);
  }
  if(Set.of("review","archive").contains(op)){
   boolean apply=op.equals("archive");require(body.keySet().equals(apply?Set.of("operation","cutoff","proof","key","confirm"):Set.of("operation")),"Provide exact archive review fields");long latest=now-((Number)current.get("days")).longValue()*86400000L,cutoff=latest;String key="",fingerprint="";
   if(apply){require(Boolean.TRUE.equals(body.get("confirm")),"Confirm the reviewed archive");key=WorkJobs.text(body.get("key"),32);require(key.matches("[0-9a-f]{32}"),"Use a 32-character archive key");String supplied=Objects.toString(body.get("cutoff"),"");require(supplied.matches("[0-9]{1,15}"),"Use the reviewed cutoff");cutoff=Long.parseLong(supplied);require(cutoff<=latest,"Cutoff exceeds the current retention policy");String reviewProof=WorkJobs.text(body.get("proof"),64);require(reviewProof.matches("[0-9a-f]{64}"),"Use the exact review proof");fingerprint=proof(db,map("cutoff",cutoff,"proof",reviewProof));var previous=db.one("SELECT fingerprint FROM os_delivery_archive WHERE batch_id=?",key);if(previous!=null){if(!fingerprint.equals(previous.get("fingerprint")))throw new Failure(409,"Archive key identifies a different review");return map("review",null,"receipt",receipt(db,key));}}
   var selected=rows(db,cutoff);String reviewProof=proof(db,map("policy",current,"cutoff",cutoff,"rows",selected));var review=map("operation","archive","cutoff",Long.toString(cutoff),"proof",reviewProof,"rows",visible(selected),"batch_id","");if(!apply)return map("review",review,"receipt",null);if(!reviewProof.equals(body.get("proof")))throw new Failure(409,"Policy, holds, authority or selected metadata changed; review again");require(!selected.isEmpty(),"No eligible metadata to archive");require(db.count("SELECT COUNT(*) FROM os_delivery_archive")<1000 && db.count("SELECT COALESCE(SUM(item_count),0) FROM os_delivery_archive WHERE state='archived'")+selected.size()<=5000,"Archive capacity reached");String envelope=Outbox.encrypt(store.secret+":delivery-archive-v1",JSON.writeValueAsString(map("batch_id",key,"rows",selected)));
   db.update("INSERT INTO os_delivery_archive(batch_id,state,created,item_count,fingerprint,envelope,detail) VALUES(?,'archived',?,?,?,?,?)",key,now(),selected.size(),fingerprint,envelope,JSON.writeValueAsString(map("policy",current,"cutoff",cutoff,"rows",visible(selected))));for(var row:selected)db.update("DELETE FROM os_outbox WHERE job_id=?",row.get("job_id"));SecurityEvents.record(db,db.viewerId,db.viewerId,"delivery.metadata_archived",map("batch_id",key,"count",selected.size()));return map("review",null,"receipt",receipt(db,key));
  }
  boolean restore=op.equals("restore");require(body.keySet().equals(restore?Set.of("operation","batch_id","proof","confirm"):Set.of("operation","batch_id")),"Provide exact restore fields");String key=WorkJobs.text(body.get("batch_id"),32);require(key.matches("[0-9a-f]{32}"),"Use an exact archive batch ID");var batch=db.one("SELECT * FROM os_delivery_archive WHERE batch_id=?",key);if(batch==null)throw new Failure(404,"Archive batch not found");if(restore)require(Boolean.TRUE.equals(body.get("confirm")),"Confirm metadata restoration");if(batch.get("state").equals("restored"))return map("review",null,"receipt",receipt(db,key));var selected=contents(store,batch);restorable(db,selected);String reviewProof=proof(db,batch);if(!restore)return map("review",map("operation","restore","batch_id",key,"proof",reviewProof,"cutoff","","rows",visible(selected)),"receipt",null);if(!reviewProof.equals(body.get("proof")))throw new Failure(409,"Archive or authority changed; review restoration again");for(var row:selected)db.update("INSERT INTO os_outbox(job_id,kind,reference_id,envelope,state,attempts,available_at,expires_at,created_at,lease,error) VALUES(?,?,?,'',?,?,?,?,?,'',?)",row.get("job_id"),row.get("kind"),row.get("reference_id"),row.get("state"),row.get("attempts"),row.get("available_at"),row.get("expires_at"),row.get("created_at"),row.get("error"));db.update("UPDATE os_delivery_archive SET state='restored',envelope='' WHERE batch_id=?",key);SecurityEvents.record(db,db.viewerId,db.viewerId,"delivery.metadata_restored",map("batch_id",key,"count",selected.size()));return map("review",null,"receipt",receipt(db,key));
 }
}
